python3 - <<'EOF'
import sqlite3, hashlib
conn = sqlite3.connect("user_credentials.db")
cur = conn.cursor()
cur.execute("SELECT username, password_hash FROM users LIMIT 3")
for u, h in cur.fetchall():
    print(u, "len=", len(h), "hex?", all(c in '0123456789abcdef' for c in h))

# probe: do common passwords match as plain sha256 of the password?
def probe(guess):
    return hashlib.sha256(guess.encode()).hexdigest()
candidates = ["password","Password1","admin","admin123","password123","Password123!","changeme","user"]
cur.execute("SELECT username, password_hash FROM users")
rows = cur.fetchall()
for guess in candidates:
    h = probe(guess)
    for u, ph in rows:
        if ph == h:
            print("MATCH:", u, guess)
EOF
